WITH j(d, n) AS (VALUES  ('2026-01-15'::date, 'Municipal Corporation Elections (Maharashtra)'),  ('2026-01-26'::date, 'Republic Day'),  ('2026-03-03'::date, 'Holi'),  ('2026-03-26'::date, 'Shri Ram Navami'),  ('2026-03-31'::date, 'Shri Mahavir Jayanti'),  ('2026-04-03'::date, 'Good Friday'),  ('2026-04-14'::date, 'Dr. Baba Saheb Ambedkar Jayanti'),  ('2026-05-01'::date, 'Maharashtra Day'),  ('2026-05-28'::date, 'Bakri Eid'),  ('2026-06-26'::date, 'Moharram'),  ('2026-09-14'::date, 'Ganesh Chaturthi'),  ('2026-10-02'::date, 'Mahatma Gandhi Jayanti'),  ('2026-10-20'::date, 'Dussehra'),  ('2026-11-10'::date, 'Diwali-Balipratipada'),  ('2026-11-24'::date, 'Prakash Gurpurb Sri Guru Nanak Dev')) INSERT INTO trading_calendar AS t (trade_date, is_open, is_special_session, holiday_name, notes, created_at, updated_at) SELECT d, false, false, n, 'closed (S100 R22: NSE holiday per trading_calendar.json)', now(), now() FROM j ON CONFLICT (trade_date) DO UPDATE SET is_open = false, is_special_session = false, holiday_name = EXCLUDED.holiday_name, notes = 'closed (S100 R22: NSE holiday per trading_calendar.json)', final_eod_ltp_time = NULL, updated_at = now() WHERE t.holiday_name IS DISTINCT FROM EXCLUDED.holiday_name OR t.is_open OR t.notes = 'Normal trading day' RETURNING trade_date, holiday_name, (xmax = 0) AS inserted;

-- Verification (run on its own):
WITH j(d, n) AS (VALUES  ('2026-01-15'::date, 'Municipal Corporation Elections (Maharashtra)'),  ('2026-01-26'::date, 'Republic Day'),  ('2026-03-03'::date, 'Holi'),  ('2026-03-26'::date, 'Shri Ram Navami'),  ('2026-03-31'::date, 'Shri Mahavir Jayanti'),  ('2026-04-03'::date, 'Good Friday'),  ('2026-04-14'::date, 'Dr. Baba Saheb Ambedkar Jayanti'),  ('2026-05-01'::date, 'Maharashtra Day'),  ('2026-05-28'::date, 'Bakri Eid'),  ('2026-06-26'::date, 'Moharram'),  ('2026-09-14'::date, 'Ganesh Chaturthi'),  ('2026-10-02'::date, 'Mahatma Gandhi Jayanti'),  ('2026-10-20'::date, 'Dussehra'),  ('2026-11-10'::date, 'Diwali-Balipratipada'),  ('2026-11-24'::date, 'Prakash Gurpurb Sri Guru Nanak Dev')) SELECT count(t.trade_date) AS rows_present, count(*) FILTER (WHERE t.is_open = false AND t.holiday_name = j.n) AS closed_and_named, count(*) FILTER (WHERE t.notes = 'Normal trading day') AS normal_label_left, count(*) FILTER (WHERE t.notes = 'closed (S100 R22: NSE holiday per trading_calendar.json)') AS touched_by_s100 FROM j LEFT JOIN trading_calendar t ON t.trade_date = j.d;
